1	import { useState, useRef, useEffect, useMemo } from 'react';
2	import type { Event } from '../../types/Event';
3	import type { Round } from '../../types/Round';
4	import { categoryForAction, colorForAction, iconForAction, matchFilter, formatFrameClock } from './taxonomy';
5	
6	const TL = { ruler: 26, round: 30, state: 30, lane: 46, head: 132 };
7	
8	function useMeasure(): [React.RefObject<HTMLDivElement | null>, number] {
9	  const ref = useRef<HTMLDivElement>(null);
10	  const [w, setW] = useState(0);
11	  useEffect(() => {
12	    if (!ref.current) return;
13	    const ro = new ResizeObserver(es => { for (const e of es) setW(e.contentRect.width); });
14	    ro.observe(ref.current);
15	    return () => ro.disconnect();
16	  }, []);
17	  return [ref, w];
18	}
19	
20	function fmtSec(s: number): string {
21	  const m = Math.floor(s / 60);
22	  const sec = Math.floor(s % 60);
23	  return `${m}:${String(sec).padStart(2, '0')}`;
24	}
25	
26	function laneFor(e: Event, redId: number | null, blueId: number | null): 'red' | 'blue' | null {
27	  if (e.fighter_id == null) return null;
28	  if (e.fighter_id === redId) return 'red';
29	  if (e.fighter_id === blueId) return 'blue';
30	  return null;
31	}
32	
33	interface Hover { e: Event; x: number; color: string }
34	
35	interface ClipProps {
36	  e: Event;
37	  x: number;
38	  color: string;
39	  flash: boolean;
40	  onSeek: (frame: number) => void;
41	  onHover: (h: Hover | null) => void;
42	}
43	
44	function Clip({ e, x, color, flash, onSeek, onHover }: ClipProps) {
45	  return (
46	    <button
47	      className="tl-clip"
48	      onPointerDown={ev => ev.stopPropagation()}
49	      onClick={ev => { ev.stopPropagation(); onSeek(e.frame); }}
50	      onMouseEnter={ev => onHover({ e, x: (ev.currentTarget as HTMLElement).offsetLeft, color })}
51	      onMouseLeave={() => onHover(null)}
52	      style={{
53	        position: 'absolute', left: x - 11, top: (TL.lane - 30) / 2, width: 22, height: 30, borderRadius: 7,
54	        display: 'grid', placeItems: 'center', cursor: 'pointer', zIndex: flash ? 6 : 4, padding: 0,
55	        transition: 'transform .1s',
56	        border: `1px solid color-mix(in srgb, ${color} ${flash ? 90 : 55}%, transparent)`,
57	        background: `color-mix(in srgb, ${color} ${flash ? 34 : 18}%, var(--surface-inner))`,
58	        boxShadow: flash ? `0 0 0 1.5px ${color}, 0 0 16px -2px ${color}` : 'none',
59	        animation: 'feed-in .25s ease-out',
60	      }}
61	    >
62	      <span className="material-symbols-outlined" style={{ fontSize: 16, color }}>{iconForAction(e.action)}</span>
63	    </button>
64	  );
65	}
66	
67	interface AnnotationTimelineProps {
68	  events: Event[];
69	  rounds: Round[];
70	  duration: number;
71	  fps: number;
72	  currentFrame: number;
73	  onSeek: (frame: number) => void;
74	  onSetPlaying: (playing: boolean) => void;
75	  flashId: number | null;
76	  filter: string;
77	  redFighterId: number | null;
78	  blueFighterId: number | null;
79	  redName: string;
80	  blueName: string;
81	}
82	
83	export default function AnnotationTimeline({
84	  events, rounds, duration, fps, currentFrame, onSeek, onSetPlaying, flashId, filter,
85	  redFighterId, blueFighterId, redName, blueName,
86	}: AnnotationTimelineProps) {
87	  const [zoom, setZoom] = useState(1);
88	  const [hover, setHover] = useState<Hover | null>(null);
89	  const [scrollRef, scrollW] = useMeasure();
90	  const draggingRef = useRef(false);
91	
92	  const time = (currentFrame - 1) / fps;
93	  const frameFor = (t: number) => Math.max(1, Math.round(t * fps) + 1);
94	  const xFor = (frame: number) => ((frame - 1) / fps) * pxPerSec;
95	
96	  const fitPx = scrollW > 0 ? scrollW / Math.max(duration, 1) : 2.2;
97	  const pxPerSec = fitPx * zoom;
98	  const W = duration * pxPerSec;
99	  const lanesTop = TL.ruler + TL.round + TL.state;
100	  const totalH = lanesTop + TL.lane * 2;
101	  const boxH = totalH + 14;
102	
103	  const fil = (e: Event) => matchFilter(categoryForAction(e.action), filter);
104	  const redEv = events.filter(e => laneFor(e, redFighterId, blueFighterId) === 'red' && e.action !== 'fight_end' && fil(e));
105	  const blueEv = events.filter(e => laneFor(e, redFighterId, blueFighterId) === 'blue' && e.action !== 'fight_end' && fil(e));
106	  const roundEv = events.filter(e => categoryForAction(e.action) === 'round' || e.action === 'fight_end');
107	  const stateEv = useMemo(
108	    () => events.filter(e => categoryForAction(e.action) === 'state').sort((a, b) => a.frame - b.frame),
109	    [events],
110	  );
111	  const segs = stateEv.map((e, i) => ({
112	    id: e.id,
113	    t0: (e.frame - 1) / fps,
114	    t1: i + 1 < stateEv.length ? (stateEv[i + 1].frame - 1) / fps : duration,
115	    grapple: e.action === 'state_grappling',
116	  }));
117	
118	  const targets = [5, 10, 15, 30, 60, 120, 180];
119	  const tickEvery = targets.find(s => s * pxPerSec >= 64) || 240;
120	  const ticks: number[] = [];
121	  for (let t = 0; t <= duration; t += tickEvery) ticks.push(t);
122	
123	  const scrubRef = useRef<(clientX: number) => void>(() => {});
124	  scrubRef.current = (clientX: number) => {
125	    const el = scrollRef.current;
126	    if (!el) return;
127	    const r = el.getBoundingClientRect();
128	    const t = (clientX - r.left + el.scrollLeft) / pxPerSec;
129	    onSeek(frameFor(Math.max(0, Math.min(duration, t))));
130	  };
131	  useEffect(() => {
132	    const move = (e: PointerEvent) => { if (draggingRef.current) scrubRef.current(e.clientX); };
133	    const up = () => { draggingRef.current = false; };
134	    window.addEventListener('pointermove', move);
135	    window.addEventListener('pointerup', up);
136	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
137	  }, []);
138	  const startScrub = (e: React.PointerEvent) => { draggingRef.current = true; onSetPlaying(false); scrubRef.current(e.clientX); };
139	
140	  useEffect(() => {
141	    const el = scrollRef.current;
142	    if (!el) return;
143	    const x = xFor(currentFrame);
144	    const L = el.scrollLeft;
145	    const R = L + el.clientWidth;
146	    if (x < L + 48 || x > R - 48) el.scrollLeft = x - el.clientWidth / 2;
147	    // eslint-disable-next-line react-hooks/exhaustive-deps
148	  }, [time, pxPerSec]);
149	
150	  const TrackHead = ({ h, children, top }: { h: number; children: React.ReactNode; top: number }) => (
151	    <div style={{
152	      position: 'absolute', top, left: 0, height: h, width: TL.head, display: 'flex', alignItems: 'center', gap: 8,
153	      padding: '0 12px', boxSizing: 'border-box', borderBottom: '1px solid var(--border-subtle)',
154	      borderRight: '1px solid var(--border-glass)', background: 'var(--surface-inner)',
155	    }}>{children}</div>
156	  );
157	
158	  const playX = xFor(currentFrame);
159	
160	  return (
161	    <div style={{ display: 'flex', position: 'relative', height: boxH, borderRadius: 12, overflow: 'hidden', border: '1px solid var(--border-subtle)' }}>
162	      <div style={{ position: 'relative', width: TL.head, flexShrink: 0, background: 'var(--surface-inner)', zIndex: 8 }}>
163	        <div style={{
164	          position: 'absolute', top: 0, height: TL.ruler, width: TL.head, borderBottom: '1px solid var(--border-glass)',
165	          borderRight: '1px solid var(--border-glass)', display: 'flex', alignItems: 'center', padding: '0 12px',
166	          fontSize: 9, fontWeight: 800, letterSpacing: '0.1em', color: 'var(--text-disabled)',
167	        }}>TRACKS</div>
168	        <TrackHead top={TL.ruler} h={TL.round}>
169	          <span className="material-symbols-outlined" style={{ fontSize: 15, color: 'var(--green-500)' }}>flag</span>
170	          <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.06em', color: 'var(--text-tertiary)' }}>ROUNDS</span>
171	        </TrackHead>
172	        <TrackHead top={TL.ruler + TL.round} h={TL.state}>
173	          <span className="material-symbols-outlined" style={{ fontSize: 15, color: 'var(--slate-400)' }}>change_circle</span>
174	          <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.06em', color: 'var(--text-tertiary)' }}>STATE</span>
175	        </TrackHead>
176	        <TrackHead top={lanesTop} h={TL.lane}>
177	          <span style={{ width: 9, height: 9, borderRadius: 2, background: 'var(--f-red)' }} />
178	          <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)' }}>{redName}</span>
179	        </TrackHead>
180	        <TrackHead top={lanesTop + TL.lane} h={TL.lane}>
181	          <span style={{ width: 9, height: 9, borderRadius: 2, background: 'var(--f-blue)' }} />
182	          <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)' }}>{blueName}</span>
183	        </TrackHead>
184	      </div>
185	
186	      <div ref={scrollRef} className="tl-scroll" style={{ flex: 1, overflowX: 'auto', overflowY: 'hidden', position: 'relative' }}>
187	        <div style={{ position: 'relative', width: W, height: totalH, minWidth: '100%' }}>
188	          <div style={{ position: 'absolute', top: TL.ruler, left: 0, width: '100%', height: TL.round, background: 'rgba(255,255,255,0.018)' }} />
189	          <div style={{ position: 'absolute', top: lanesTop + TL.lane, left: 0, width: '100%', height: TL.lane, background: 'rgba(255,255,255,0.022)' }} />
190	
191	          {rounds.map(r => (
192	            <div key={'rb' + r.id}>
193	              {r.round_number > 1 && (
194	                <div style={{ position: 'absolute', top: TL.ruler, left: xFor(r.start_frame), width: 1, height: totalH - TL.ruler, background: 'rgba(255,255,255,0.12)' }} />
195	              )}
196	              <div style={{ position: 'absolute', top: 4, left: xFor(r.start_frame) + 6, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.08em', color: 'var(--text-disabled)', pointerEvents: 'none' }}>
197	                R{r.round_number}
198	              </div>
199	            </div>
200	          ))}
201	
202	          <div
203	            onPointerDown={startScrub}
204	            className="tl-ruler"
205	            style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: TL.ruler, cursor: 'ew-resize', borderBottom: '1px solid var(--border-glass)' }}
206	          >
207	            {ticks.map(t => (
208	              <div key={t} style={{ position: 'absolute', left: t * pxPerSec, top: 0, height: '100%', pointerEvents: 'none' }}>
209	                <div style={{ position: 'absolute', left: 0, bottom: 0, width: 1, height: 7, background: 'rgba(255,255,255,0.22)' }} />
210	                <span style={{ position: 'absolute', left: 5, top: 5, fontSize: 10, fontWeight: 700, color: 'var(--text-muted)', fontVariantNumeric: 'tabular-nums' }}>{fmtSec(t)}</span>
211	              </div>
212	            ))}
213	          </div>
214	
215	          <div onPointerDown={startScrub} style={{ position: 'absolute', top: TL.ruler, left: 0, width: '100%', height: totalH - TL.ruler, cursor: 'ew-resize', zIndex: 1 }} />
216	
217	          {segs.map(s => {
218	            const c = s.grapple ? 'var(--orange-400)' : 'var(--accent)';
219	            const w = Math.max(2, s.t1 * pxPerSec - s.t0 * pxPerSec);
220	            return (
221	              <div
