72	// The palette has no landed/blocked toggle — every strike it logs is "landed".
73	// Grapple/outcome-adjacent actions (attempts, submissions) have no confirmed
74	// landed/missed outcome, so success stays null/unknown for those.
75	const SUCCESS_TRUE_ACTIONS = new Set([
76	  'jab', 'straight_right', 'left_hook', 'right_hook', 'left_uppercut', 'right_uppercut',
77	  'calf_kick', 'low_kick', 'middle_kick', 'high_kick', 'elbow', 'knee', 'knockdown',
78	]);
