84	export function categoryForAction(action: string | null): EventCat {
85	  if (!action) return 'state';
86	  if (action === 'fight_end' || action === 'submission_attempt') return 'event';
87	  if (action.startsWith('takedown_')) return 'grapple';
88	  if (action.startsWith('state_')) return 'state';
89	  if (action.startsWith('round_')) return 'round';
90	  return 'strike';
91	}
92	
93	export function colorForAction(action: string | null): string {
94	  if (!action) return 'var(--text-muted)';
95	  if (action === 'knockdown') return 'var(--f-red)';
96	  if (action === 'fight_end' || action === 'submission_attempt') return 'var(--purple-600)';
97	  if (action.startsWith('takedown_')) return 'var(--orange-400)';
98	  if (action.startsWith('state_')) return 'var(--slate-400)';
99	  if (action.startsWith('round_')) return 'var(--green-500)';
100	  return 'var(--accent)';
101	}
102	
103	export function iconForAction(action: string | null): string {
104	  if (!action) return 'radio_button_checked';
105	  if (action === 'knockdown') return 'sports_mma';
106	  if (action === 'fight_end') return 'sports_score';
107	  if (action === 'submission_attempt') return 'crisis_alert';
108	  if (action.startsWith('takedown_')) return 'sports_kabaddi';
109	  if (action.startsWith('state_')) return 'change_circle';
110	  if (action.startsWith('round_')) return 'timer';
111	  return 'bolt';
112	}
113	
114	export const FILTERS: { key: string; label: string }[] = [
115	  { key: 'all', label: 'All' },
116	  { key: 'strike', label: 'Strikes' },
117	  { key: 'state', label: 'Fight State' },
118	  { key: 'grapple', label: 'Grapple' },
119	];
120	
121	export function matchFilter(cat: EventCat, filter: string): boolean {
122	  if (filter === 'all') return true;
123	  if (filter === 'grapple') return cat === 'grapple' || cat === 'event';
124	  if (filter === 'state') return cat === 'state' || cat === 'round';
125	  return cat === filter;
126	}
127	
128	export const PLAYBACK_KEYS: { k: string[]; label: string }[] = [
129	  { k: ['Space'], label: 'Play / pause' },
130	  { k: ['←', '→'], label: 'Seek ±1 s' },
131	  { k: ['⇧', '←/→'], label: 'Seek ±5 s' },
132	  { k: [',', '.'], label: 'Step ±1 frame' },
133	];
134	
135	export const EDIT_KEYS: { k: string[]; label: string }[] = [
136	  { k: ['R'], label: 'Select red corner' },
137	  { k: ['B'], label: 'Select blue corner' },
138	  { k: ['Esc'], label: 'Deselect fighter' },
139	  { k: ['Z'], label: 'Undo last event' },
140	];
141	
142	/** Frame (1-based) → "m:ss" clock, matching the currentFrame = floor(t*fps)+1 contract. */
143	export function formatFrameClock(frame: number, fps: number): string {
144	  const seconds = Math.max(0, (frame - 1) / fps);
145	  const m = Math.floor(seconds / 60);
146	  const s = Math.floor(seconds % 60);
147	  return `${m}:${String(s).padStart(2, '0')}`;
148	}
