1	/**
2	 * Single source of truth for the manual-annotation palette: each ToolItem
3	 * drives the palette button, its keyboard shortcut, and the keyboard legend
4	 * simultaneously. Round boundaries aren't here — real Round rows already
5	 * exist from AI segmentation (see ai/fight_processing/write_frames_and_rounds).
6	 * Only "fight end" stays manual since no stage detects a fight's conclusion.
7	 */
8	
9	export type Corner = 'red' | 'blue';
10	export type EventCat = 'strike' | 'grapple' | 'state' | 'round' | 'event';
11	export type Target = 'head' | 'body' | 'leg';
12	
13	export interface ToolItem {
14	  key: string;
15	  num?: string;
16	  action: string;
17	  name: string;
18	  text: (fighterName: string, target?: Target) => string;
19	  needsFighter: boolean;
20	  /** Shift-modified: plain key = head, Shift+key = body. Read via e.code + e.shiftKey. */
21	  hasTarget?: boolean;
22	  /** Kicks already encode target in the action name — no modifier needed. */
23	  fixedTarget?: Target;
24	}
25	
26	export interface ToolGroup {
27	  group: string;
28	  note?: string;
29	  items: ToolItem[];
30	}
31	
32	// Shared by every hand strike + elbow so the description always reflects the
33	// real target instead of a value baked in per-action (right_hook used to be
34	// hardcoded "to the body" regardless of where it actually landed).
35	const HAND_STRIKE_NAMES: Record<string, string> = {
36	  jab: 'jab',
37	  straight_right: 'straight right',
38	  left_hook: 'left hook',
39	  right_hook: 'right hook',
40	  left_uppercut: 'left uppercut',
41	  right_uppercut: 'right uppercut',
42	  elbow: 'elbow',
43	};
44	
45	function handStrikeText(action: string, fighterName: string, target: Target = 'head'): string {
46	  return `${fighterName} ${HAND_STRIKE_NAMES[action]} to the ${target}`;
47	}
48	
49	export const TOOL_GROUPS: ToolGroup[] = [
50	  {
51	    group: 'Strikes',
52	    note: 'Hand strikes use boxing numbers · Shift = body',
53	    items: [
54	      { key: '1', num: '1', action: 'jab', name: 'Jab', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('jab', f, t) },
55	      { key: '2', num: '2', action: 'straight_right', name: 'Straight right', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('straight_right', f, t) },
56	      { key: '3', num: '3', action: 'left_hook', name: 'Left hook', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('left_hook', f, t) },
57	      { key: '4', num: '4', action: 'right_hook', name: 'Right hook', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('right_hook', f, t) },
58	      { key: '5', num: '5', action: 'left_uppercut', name: 'Left uppercut', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('left_uppercut', f, t) },
59	      { key: '6', num: '6', action: 'right_uppercut', name: 'Right uppercut', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('right_uppercut', f, t) },
60	      { key: 'c', action: 'calf_kick', name: 'Calf kick', needsFighter: true, fixedTarget: 'leg', text: f => `${f} calf kick` },
61	      { key: 'l', action: 'low_kick', name: 'Low kick', needsFighter: true, fixedTarget: 'leg', text: f => `${f} low kick` },
62	      { key: 'm', action: 'middle_kick', name: 'Middle kick', needsFighter: true, fixedTarget: 'body', text: f => `${f} middle kick to the body` },
63	      { key: 'h', action: 'high_kick', name: 'High kick', needsFighter: true, fixedTarget: 'head', text: f => `${f} high kick to the head` },
64	      { key: 'e', action: 'elbow', name: 'Elbow', needsFighter: true, hasTarget: true, text: (f, t) => handStrikeText('elbow', f, t) },
65	      { key: 'n', action: 'knee', name: 'Knee', needsFighter: true, text: f => `${f} knee in the clinch` },
66	    ],
67	  },
68	  {
69	    group: 'Grappling',
70	    items: [
71	      { key: 't', action: 'takedown_attempt', name: 'Takedown attempt', needsFighter: true, text: f => `${f} shoots for a takedown` },
72	      { key: 'd', action: 'takedown_defended', name: 'Takedown defended', needsFighter: true, text: f => `${f} defends the takedown` },
73	      { key: 's', action: 'submission_attempt', name: 'Submission', needsFighter: true, text: f => `${f} threatens a submission` },
74	    ],
75	  },
76	  {
77	    group: 'Outcome',
78	    items: [
79	      { key: 'x', action: 'knockdown', name: 'Knockdown', needsFighter: true, text: f => `${f} scores a KNOCKDOWN` },
80	    ],
81	  },
82	  {
83	    group: 'Fight state',
84	    items: [
85	      { key: 'w', action: 'state_striking', name: 'Striking', needsFighter: false, text: () => 'Fight state → STRIKING' },
86	      { key: 'f', action: 'state_clinch', name: 'Clinch', needsFighter: false, text: () => 'Fight state → CLINCH' },
87	      { key: 'g', action: 'state_ground', name: 'Ground', needsFighter: false, text: () => 'Fight state → GROUND' },
88	    ],
89	  },
90	];
91	
92	export const KEYMAP: Record<string, ToolItem> = {};
93	TOOL_GROUPS.forEach(g => g.items.forEach(it => { KEYMAP[it.key] = it; }));
94	
95	// Landed-vs-missed is deferred (MVP target is "count strikes thrown"), so every
96	// strike logs success=null — outcome unknown, not a claim that it landed.
97	// `knockdown` is the one exception: it is never a default, so a logged
98	// knockdown really did land.
99	const SUCCESS_TRUE_ACTIONS = new Set(['knockdown']);
100	
101	export function successForAction(action: string): boolean | null {
102	  return SUCCESS_TRUE_ACTIONS.has(action) ? true : null;
103	}
104	
105	export function categoryForAction(action: string | null): EventCat {
106	  if (!action) return 'state';
107	  if (action === 'fight_end' || action === 'submission_attempt') return 'event';
108	  if (action.startsWith('takedown_')) return 'grapple';
109	  if (action.startsWith('state_')) return 'state';
110	  if (action.startsWith('round_')) return 'round';
111	  return 'strike';
112	}
113	
114	export function colorForAction(action: string | null): string {
115	  if (!action) return 'var(--text-muted)';
116	  if (action === 'knockdown') return 'var(--f-red)';
117	  if (action === 'fight_end' || action === 'submission_attempt') return 'var(--purple-600)';
118	  if (action.startsWith('takedown_')) return 'var(--orange-400)';
119	  if (action.startsWith('state_')) return 'var(--slate-400)';
120	  if (action.startsWith('round_')) return 'var(--green-500)';
121	  return 'var(--accent)';
122	}
123	
124	export function iconForAction(action: string | null): string {
125	  if (!action) return 'radio_button_checked';
126	  if (action === 'knockdown') return 'sports_mma';
127	  if (action === 'fight_end') return 'sports_score';
128	  if (action === 'submission_attempt') return 'crisis_alert';
129	  if (action.startsWith('takedown_')) return 'sports_kabaddi';
130	  if (action.startsWith('state_')) return 'change_circle';
131	  if (action.startsWith('round_')) return 'timer';
132	  return 'bolt';
133	}
134	
135	export const FILTERS: { key: string; label: string }[] = [
136	  { key: 'all', label: 'All' },
137	  { key: 'strike', label: 'Strikes' },
138	  { key: 'state', label: 'Fight State' },
139	  { key: 'grapple', label: 'Grapple' },
140	];
141	
142	export function matchFilter(cat: EventCat, filter: string): boolean {
143	  if (filter === 'all') return true;
