  {
    group: 'Grappling',
    items: [
      { key: 't', action: 'takedown_attempt', name: 'Takedown attempt', needsFighter: true, text: f => `${f} shoots for a takedown` },
      { key: 'y', action: 'takedown_landed', name: 'Takedown landed', needsFighter: true, text: f => `${f} lands a takedown` },
