1	import { useState, useRef, useEffect, useMemo } from 'react';
2	import type { LabelEvent } from '../../types/LabelEvent';
3	import type { LabelSpan, SpanKind } from '../../types/LabelSpan';
4	import type { Round } from '../../types/Round';
5	import { categoryForAction, colorForAction, iconForAction, matchFilter, formatFrameClock } from './taxonomy';
6	
7	const TL = { ruler: 26, round: 30, state: 30, span: 26, lane: 46, head: 132 };
8	
9	const SPAN_COLOR: Record<SpanKind, string> = {
10	  round: 'var(--green-500)',
11	  corner_swap: 'var(--purple-600)',
12	  excluded: 'var(--text-muted)',
13	};
14	
15	function useMeasure(): [React.RefObject<HTMLDivElement | null>, number] {
16	  const ref = useRef<HTMLDivElement>(null);
17	  const [w, setW] = useState(0);
18	  useEffect(() => {
19	    if (!ref.current) return;
20	    const ro = new ResizeObserver(es => { for (const e of es) setW(e.contentRect.width); });
21	    ro.observe(ref.current);
22	    return () => ro.disconnect();
23	  }, []);
24	  return [ref, w];
25	}
26	
27	function fmtSec(s: number): string {
28	  const m = Math.floor(s / 60);
29	  const sec = Math.floor(s % 60);
30	  return `${m}:${String(sec).padStart(2, '0')}`;
31	}
32	
33	function laneFor(e: LabelEvent): 'red' | 'blue' | null {
34	  if (e.corner === 0) return 'red';
35	  if (e.corner === 1) return 'blue';
36	  return null;
37	}
38	
39	interface Hover { e: LabelEvent; x: number; color: string }
40	
41	interface ClipProps {
42	  e: LabelEvent;
43	  x: number;
44	  color: string;
45	  flash: boolean;
46	  onSeek: (frame: number) => void;
47	  onHover: (h: Hover | null) => void;
48	}
49	
50	function Clip({ e, x, color, flash, onSeek, onHover }: ClipProps) {
51	  return (
52	    <button
53	      className="tl-clip"
54	      onPointerDown={ev => ev.stopPropagation()}
55	      onClick={ev => { ev.stopPropagation(); onSeek(e.frame); }}
56	      onMouseEnter={ev => onHover({ e, x: (ev.currentTarget as HTMLElement).offsetLeft, color })}
57	      onMouseLeave={() => onHover(null)}
58	      style={{
59	        position: 'absolute', left: x - 11, top: (TL.lane - 30) / 2, width: 22, height: 30, borderRadius: 7,
60	        display: 'grid', placeItems: 'center', cursor: 'pointer', zIndex: flash ? 6 : 4, padding: 0,
61	        transition: 'transform .1s',
62	        border: `1px solid color-mix(in srgb, ${color} ${flash ? 90 : 55}%, transparent)`,
63	        background: `color-mix(in srgb, ${color} ${flash ? 34 : 18}%, var(--surface-inner))`,
64	        boxShadow: flash ? `0 0 0 1.5px ${color}, 0 0 16px -2px ${color}` : 'none',
65	        animation: 'feed-in .25s ease-out',
66	      }}
67	    >
68	      <span className="material-symbols-outlined" style={{ fontSize: 16, color }}>{iconForAction(e.action)}</span>
69	    </button>
70	  );
71	}
72	
73	interface AnnotationTimelineProps {
74	  events: LabelEvent[];
75	  spans: LabelSpan[];
76	  rounds: Round[];
77	  duration: number;
78	  fps: number;
79	  currentFrame: number;
80	  onSeek: (frame: number) => void;
81	  onSetPlaying: (playing: boolean) => void;
82	  onUpdateSpan: (id: number, patch: { start_frame?: number; end_frame?: number }) => void;
83	  onDeleteSpan: (id: number) => void;
84	  flashId: number | null;
85	  filter: string;
86	  redName: string;
87	  blueName: string;
88	}
89	
90	export default function AnnotationTimeline({
91	  events, spans, rounds, duration, fps, currentFrame, onSeek, onSetPlaying, onUpdateSpan, onDeleteSpan,
92	  flashId, filter, redName, blueName,
93	}: AnnotationTimelineProps) {
94	  const [zoom, setZoom] = useState(1);
95	  const [hover, setHover] = useState<Hover | null>(null);
96	  const [scrollRef, scrollW] = useMeasure();
97	  const draggingRef = useRef(false);
98	
99	  const time = (currentFrame - 1) / fps;
100	  const frameFor = (t: number) => Math.max(1, Math.round(t * fps) + 1);
101	  const xFor = (frame: number) => ((frame - 1) / fps) * pxPerSec;
102	
103	  const fitPx = scrollW > 0 ? scrollW / Math.max(duration, 1) : 2.2;
104	  const pxPerSec = fitPx * zoom;
105	  const W = duration * pxPerSec;
106	  const spansTop = TL.ruler + TL.round + TL.state;
107	  const lanesTop = spansTop + TL.span * 2;
108	  const totalH = lanesTop + TL.lane * 2;
109	  const boxH = totalH + 14;
110	
111	  // Live edge being dragged, so the block redraws smoothly before the PUT commits.
112	  const dragRef = useRef<{ id: number; edge: 'start' | 'end' } | null>(null);
113	  const [dragFrame, setDragFrame] = useState<number | null>(null);
114	
115	  const fil = (e: LabelEvent) => matchFilter(categoryForAction(e.action), filter);
116	  const redEv = events.filter(e => laneFor(e) === 'red' && e.action !== 'fight_end' && fil(e));
117	  const blueEv = events.filter(e => laneFor(e) === 'blue' && e.action !== 'fight_end' && fil(e));
118	  const roundEv = events.filter(e => categoryForAction(e.action) === 'round' || e.action === 'fight_end');
119	  const stateEv = useMemo(
120	    () => events.filter(e => categoryForAction(e.action) === 'state').sort((a, b) => a.frame - b.frame),
121	    [events],
122	  );
123	  const segs = stateEv.map((e, i) => ({
124	    id: e.id,
125	    t0: (e.frame - 1) / fps,
126	    t1: i + 1 < stateEv.length ? (stateEv[i + 1].frame - 1) / fps : duration,
127	    state: e.action === 'state_clinch' ? 'CLINCH' : e.action === 'state_ground' ? 'GROUND' : 'STRIKING',
128	  }));
129	
130	  const roundSpans = spans.filter(s => s.kind === 'round');
131	  const cornerSwapSpans = spans.filter(s => s.kind === 'corner_swap');
132	  const excludedSpans = spans.filter(s => s.kind === 'excluded');
133	
134	  const targets = [5, 10, 15, 30, 60, 120, 180];
135	  const tickEvery = targets.find(s => s * pxPerSec >= 64) || 240;
136	  const ticks: number[] = [];
137	  for (let t = 0; t <= duration; t += tickEvery) ticks.push(t);
138	
139	  const scrubRef = useRef<(clientX: number) => void>(() => {});
140	  scrubRef.current = (clientX: number) => {
141	    const el = scrollRef.current;
142	    if (!el) return;
143	    const r = el.getBoundingClientRect();
144	    const t = (clientX - r.left + el.scrollLeft) / pxPerSec;
145	    onSeek(frameFor(Math.max(0, Math.min(duration, t))));
146	  };
147	  useEffect(() => {
148	    const move = (e: PointerEvent) => { if (draggingRef.current) scrubRef.current(e.clientX); };
149	    const up = () => { draggingRef.current = false; };
150	    window.addEventListener('pointermove', move);
151	    window.addEventListener('pointerup', up);
152	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
153	  }, []);
154	  const startScrub = (e: React.PointerEvent) => { draggingRef.current = true; onSetPlaying(false); scrubRef.current(e.clientX); };
155	
156	  // Edge-drag for span blocks (round / corner_swap / excluded resize handles).
157	  useEffect(() => {
158	    const move = (e: PointerEvent) => {
159	      const d = dragRef.current;
160	      const el = scrollRef.current;
161	      if (!d || !el) return;
162	      const r = el.getBoundingClientRect();
163	      const t = (e.clientX - r.left + el.scrollLeft) / pxPerSec;
164	      setDragFrame(frameFor(Math.max(0, Math.min(duration, t))));
165	    };
166	    const up = () => {
167	      const d = dragRef.current;
168	      if (d && dragFrame != null) {
169	        onUpdateSpan(d.id, d.edge === 'start' ? { start_frame: dragFrame } : { end_frame: dragFrame });
170	      }
171	      dragRef.current = null;
172	      setDragFrame(null);
