174	    window.addEventListener('pointermove', move);
175	    window.addEventListener('pointerup', up);
176	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
177	    // eslint-disable-next-line react-hooks/exhaustive-deps
178	  }, [pxPerSec, duration, dragFrame]);
179	  const startEdgeDrag = (id: number, edge: 'start' | 'end') => (e: React.PointerEvent) => {
180	    e.stopPropagation();
181	    onSetPlaying(false);
182	    dragRef.current = { id, edge };
183	  };
184	
