186	    const el = scrollRef.current;
187	    if (!el) return;
188	    const x = xFor(currentFrame);
189	    const L = el.scrollLeft;
190	    const R = L + el.clientWidth;
191	    if (x < L + 48 || x > R - 48) el.scrollLeft = x - el.clientWidth / 2;
192	    // eslint-disable-next-line react-hooks/exhaustive-deps
