223	          border: `1px solid color-mix(in srgb, ${c} ${open ? 55 : 38}%, transparent)`,
224	          borderStyle: open ? 'dashed' : 'solid',
225	          display: 'flex', alignItems: 'center', overflow: 'hidden',
226	        }}
227	        title={s.value ? `${s.kind} — ${s.value}` : s.kind}
