297	  return (
298	    <div style={{ display: 'flex', position: 'relative', height: boxH, borderRadius: 12, overflow: 'hidden', border: '1px solid var(--border-subtle)' }}>
299	      <div style={{ position: 'relative', width: TL.head, flexShrink: 0, background: 'var(--surface-inner)', zIndex: 8 }}>
300	        <div style={{
301	          position: 'absolute', top: 0, height: TL.ruler, width: TL.head, borderBottom: '1px solid var(--border-glass)',
302	          borderRight: '1px solid var(--border-glass)', display: 'flex', alignItems: 'center', padding: '0 12px',
303	          fontSize: 9, fontWeight: 800, letterSpacing: '0.1em', color: 'var(--text-disabled)',
304	        }}>TRACKS</div>
