314	          <span className="material-symbols-outlined" style={{ fontSize: 14, color: 'var(--purple-600)' }}>swap_horiz</span>
315	          <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.05em', color: 'var(--text-tertiary)' }}>CORNER SWAP</span>
316	        </TrackHead>
